# Examine best spatial transformations/offsets where O subset L & shifted R in demos 1,3.
import numpy as np

def best(L,R,O):
 out=[]
 for k in range(4):
  t=np.rot90(R,k)
  for f in [False,True]:
   x=np.fliplr(t) if f else t
   # scan shifts keeping same output shape, zero pad
   for dr in range(-10,11):
    for dc in range(-10,11):
     Y=np.zeros(L.shape,int)
     for i in range(L.shape[0]):
      for j in range(L.shape[1]):
       ri=i-dr; rj=j-dc
       if 0<=ri<x.shape[0] and 0<=rj<x.shape[1]: Y[i,j]=x[ri,rj]
     score=int(np.sum(O & L & Y))
     out.append((score,k,f,dr,dc,int(np.sum(L&Y)),int(np.sum(O & ~(L&Y)))))
 return sorted(out,reverse=True)[:10]
print(best(L,R,O)[:10])
